import{_ as d,o as r,c,a2 as t,j as e}from"./chunks/framework.xCjF2uVY.js";const s="/nds-site/video/demo_mori.mp4",p=JSON.parse('{"title":"进度 S0–S7","description":"八个阶段各自走到哪、判据是什么、还欠什么","frontmatter":{"title":"进度 S0–S7","description":"八个阶段各自走到哪、判据是什么、还欠什么"},"headers":[],"relativePath":"progress.md","filePath":"progress.md","lastUpdated":1791250821000}'),n={name:"progress.md"};function a(i,o,l,g,_,u){return r(),c("div",null,[...o[0]||(o[0]=[t('<h1 id="进度-s0–s7" tabindex="-1">进度：S0–S7 <a class="header-anchor" href="#进度-s0–s7" aria-label="Permalink to &quot;进度：S0–S7&quot;">​</a></h1><p>计划的终点是「一个房间可自由走动探索（裁剪版）」= <strong>静态场景 + 幻影加农本体 + Link 可行走</strong>。 下表左列是计划里写死的判据，右列是现在盘上站得住的读数 —— 每条都能在 <a href="/nds-site/acceptance.html">验收门读数</a> 里 找到对应的门，每张证据图都能在 <a href="/nds-site/gallery.html">画面证据</a> 里追溯到画它的那份 ROM。</p><table tabindex="0"><thead><tr><th>阶段</th><th>计划判据（原文口径）</th><th>状态</th><th>现在的读数</th></tr></thead><tbody><tr><td><strong>S0</strong> 资产完好 + 身份确认</td><td><code>asset_verify.py</code> 全绿；角色 ROM md5 逐位不变；actor <code>0x52</code> → object ID → object 文件三者钉死</td><td>✅</td><td><code>object:378/0 other:539/1 room:388/0 scene:101/0 static:102/0</code>（dmadata 那条是良性例外）；本体 = <code>object_gnd</code>，Standard 骨架</td></tr><tr><td><strong>S1</strong> 房间 DL → JSON</td><td>逐位复现 694/408、1061/610；<code>G_MTX==0</code>；<code>Σn==unique</code>；母 DL 每条子 DL 的 tri 之和 == 房间总 tri</td><td>✅</td><td><code>room_reconcile.py</code> <strong>32/32</strong>：room_0 694 顶点/408 三角形、room_1 1061/610（opa 608 + xlu 2），两间 <code>G_MTX==0</code>，索引口径 ×2 胜，纹理字节守恒</td></tr><tr><td><strong>S2</strong> 房间纹理烘焙</td><td>纹理总和 ≤ 256 KB；TLUT 数量与 <code>LOADTLUT</code> 计数一致；<code>w*h</code>/<code>lrs+1</code>/<code>dxt</code> 互洽</td><td>✅</td><td>预算门 <strong>13/13</strong>（room_0 13,312 B、room_1 32,512 B）；机内 <code>VRAMMAP=1</code> 实测 22 段 / 66 KB / 零重叠</td></tr><tr><td><strong>S3</strong> 静态场景 ROM</td><td>GPU 读数 == S1 JSON 读数（无丢包）</td><td>✅</td><td>三个机位的 OCR 读数 <code>GPU 1018/1018</code>、<code>verts 1755 tex 22</code>、<code>BOSS 440/440</code>、<code>entry floor -193</code> 与离线现算期望值逐位相同</td></tr><tr><td><strong>S4</strong> 透视相机 + 组剔除</td><td>各 yaw 下可见组与离线 bbox 预测一致；<code>fovy=60°</code>/<code>zFar=1500</code>/<code>fogNear=940</code></td><td>✅</td><td>13 机位逐个过 <code>actual ⊆ predicted</code>；九台剔除孪生主屏 <strong>AE=0</strong>；环境参数四段（ROM 现解 == 头文件 == <code>main.c</code> 字面量 == 量具 <code>--bg</code>）一致</td></tr><tr><td><strong>S5</strong> 碰撞 + 行走</td><td><code>feet_y</code> 常量断言；推向边界被拒坐标与 COL min/max 一致</td><td>✅</td><td>行走预测器自验 FAIL 行 0；四条拒绝分支的<strong>被拒停点设备 == 离线仿真</strong>逐位相同（(15,−3626)/(−760,−2979)/(63,−2904)/(−45,−2904)）</td></tr><tr><td><strong>S5</strong> Link 剪影（走到位的机位）</td><td>— 计划里没有，本轮加的</td><td>✅</td><td>两台机位 CPU 填充 vs 实机差渲染：实机 1598 / 1656 px，位后 IoU <strong>0.878 / 0.906</strong>，一圈 100.0/100.0（这一行<strong>不判绝对摆放</strong>，相机绕玩家 orbit 是它的规范自由度）</td></tr><tr><td><strong>S6</strong> Boss 本体静态网格</td><td>竞技场里看得见幻影加农本体</td><td>✅</td><td>699 顶点/440 三角形解出；剪影门两台位后 IoU <strong>0.801 / 0.796</strong>、最优位移都是 dx=2 在带内；深度归属门近机位 <strong>Link 挡住本体 166 px、本体画进 Link 剪影内 0 px</strong>（<code>--maxover 0</code> 照样 PASS）</td></tr><tr><td><strong>S6</strong> xlu 半透明层</td><td>— 计划里只说&quot;近似&quot;</td><td>⚠ 量到极限</td><td><code>dose</code> 8523 px 100% 落在离线 footprint 内、位后 IoU 0.902（几何归因成立）；深度那侧<strong>共面 ⇒ 平局不可判</strong>（离线距离差 1.71 raw，而 DS 深度一格是 4 raw）</td></tr><tr><td><strong>S7</strong> 运行时 FK（可选项）</td><td>走路姿势随四肢变化</td><td>➖ 不需要</td><td>本体是 Standard 骨架（S0 的结论），FK 不在本场景依赖里</td></tr></tbody></table><h2 id="还欠什么" tabindex="-1">还欠什么 <a class="header-anchor" href="#还欠什么" aria-label="Permalink to &quot;还欠什么&quot;">​</a></h2><ol><li><strong>人眼判决（协议 3）没收到</strong>。数字门全部通过后，&quot;这就是森林 boss 房、纹理是对的、比例是对的&quot;这一句 必须由人看图判定，量具不代替它。素材在 <a href="/nds-site/gallery.html">画面证据</a> 的前两节（验收 ROM 三张 + 七张拼图）， 其中 <code>contact_sheet_2026-10-05_final.png</code> 是<strong>终检图</strong>：四格各只问一件事（整场景 / 本体被 Link 挡住 像不像 / 走到位后比例与四肢 / 转的是相机不是重画场景），一票判完不必翻其余六张分项。</li><li><strong>偏差 4 会被人看见</strong>：本轮按计划不做相机碰撞，房间小、<code>CAM_DIST=90</code> 而眼高只有 60 ⇒ 5975 个合法站立格里 四个朝向各有 <strong>50~55%</strong> 让眼点落进极近几何档，那个档里量具与真机对不齐（色场 WARN 的来源）。</li><li><strong>偏差 1 的归属未证</strong>：desmume 相对 CPU 量具的屏幕错位<strong>不是恒定 +3px</strong>（y180 最优是 dx=0）， 本体那四个独立读数倒是都落在 dx=2。<code>glGetFixed</code> 回读在 desmume 上不响应 ⇒ 上真机第一件事就是复测这条。</li><li><strong>角色纹理两处以决定为由关掉</strong>：本体 <code>draw_boss.c</code> 只走顶点色 + 白纹理单位元，所以幻影加农在画面里发白； 场景里的 Link 走 <code>src_scene/link_rigid.c</code>，在 <code>LINKTEX=1</code> 之前同样只绑白纹理、不发 UV，所以林克也发白。 <code>object_gnd</code> 的骨架可达 limb DL 里实测有 51 SETTIMG / 51 LOADBLOCK / 51 SETTILESIZE / 102 SETTILE / 52 SETCOMBINE （且这是下界：每条 limb DL 那条外部段 <code>G_DL</code> 按既有口径不递归），要补得走与房间同套管线的另一份口径； Link 那侧则不缺料（17 张 CI4 + 每组 <code>tex_id</code>/UV 都在盘上），缺的是把 <code>src/link_full_render.c</code> 那条链搬过来， 搬完了但<strong>默认没开</strong>（开了就是换验收实物）。两条的完整口径与实测数在 <a href="/nds-site/caveats.html">已知偏差</a> 偏差 2。 ⚠ 本页此前抄的是「190 / 97 / 54」，那是整镜像朴素 opcode 直方图把数据字节数成命令的结果，已由 docs §5 更正。</li><li><strong>偏差 5 也会被人看见</strong>：把 Link 走到竞技场沿上，他<strong>站住不动而不是掉下去</strong> —— 本轮不做重力，落点的地板 探测窗口是 <code>[feetY, feetY+6]</code>（<code>src_scene/main.c:605</code>，下界正好等于当前脚底），所以任何比当前脚底低的地面 一律被拒、整次移动作废。计划 S5 只要求&quot;站在地面、撞墙不穿&quot;，没要求 fall 状态，所以这是裁剪口径而不是 地板解漏了多边形。图上认这条看的是副屏<strong>坐标数字停住、<code>walk</code> 那对极值不再扩大</strong>，不是状态词 —— 截图前必然松键， 而 <code>moveState</code> 每帧在按键检查前复位，存档图里那个词恒为 <code>idle</code>（<code>[feetY, feetY+6]</code> 这条窗口的实测范围与配方在 <a href="/nds-site/caveats.html">已知偏差</a> 偏差 5）。</li></ol><h2 id="一句话现状" tabindex="-1">一句话现状 <a class="header-anchor" href="#一句话现状" aria-label="Permalink to &quot;一句话现状&quot;">​</a></h2><p>八阶段全部有数字门通过，<code>--rebuild</code> 87 项(其中 47 台 ROM 逐位复现；本轮唯一未闭合的是&quot;人看图说它是&quot;这件事， 以及偏差清单里那几条被明确记为<strong>范围决定 / 量具极限</strong>的差距（见 <a href="/nds-site/caveats.html">已知偏差</a>）。</p><h2 id="演示录屏-2026-10-06" tabindex="-1">演示录屏（2026-10-06） <a class="header-anchor" href="#演示录屏-2026-10-06" aria-label="Permalink to &quot;演示录屏（2026-10-06）&quot;">​</a></h2><p>ROM 自己演，不用手按：<code>DEMO=1</code> 每帧<strong>合成</strong>一个按键掩码喂给同一条行走/相机链（<code>src_scene/main.c</code> 的 <code>s_demo[]</code> 剧本：走进竞技场 → 相机转 180° → 再前进 → 回转 270° → 抬头 → 压低看本体 → 原路退回， 循环）。注入点在 START 退出判据之后，所以<strong>你碰任意键它就让出控制权</strong>，演示不是第二条没人验过的代码， 走的位置由同一份碰撞与同一步长决定。</p>',9),e("p",null,[e("video",{src:s,controls:"",autoplay:"",muted:"",loop:"",playsinline:"",preload:"metadata",style:{width:"100%","max-width":"640px",display:"block",border:"1px solid var(--vp-c-divider)"}})],-1),t('<ul><li>录屏 ROM：<code>demoMori.nds</code> = <code>a583e3a0</code>，配方 <code>make -s SCENE=moribossroom WALK=1 BOSS=1 STARTX=15 STARTZ=-2900 CAMYAW=0.0 CAMPITCH=-5.0 DEMO=1 LINKTEX=1 NAME=demoMori</code>（60 fps 口径；无头 desmume 开 <code>--disable-limiter</code> 会比这个快）。</li><li>录屏由<strong>单个</strong> desmume 实例连续抓 30 帧拼成（相邻帧间变化 31k~46k / 49152 px，29 对里没有一对静止 ⇒ 确实在动，不是同一张图重复）。格式是 <strong>MP4（397 KB）</strong>——屏幕录制一律用 mp4，不用 gif：同一份画面 gif 要 2 MB，还拖不动进度条。</li><li>这台同时带 <code>LINKTEX=1</code>，所以下面那条 Link 纹理的修复在录屏里是看得见的。</li><li>⚠ 它<strong>不在</strong>逐位复现名单里，所以&quot;这台演示 ROM 的字节&quot;目前是一次性实测；要不要扩门进去，等你点头。</li></ul><h2 id="进度记录-2026-10-06-本轮最后一次实测-不重复上面的数" tabindex="-1">进度记录 2026-10-06（本轮最后一次实测，不重复上面的数） <a class="header-anchor" href="#进度记录-2026-10-06-本轮最后一次实测-不重复上面的数" aria-label="Permalink to &quot;进度记录 2026-10-06（本轮最后一次实测，不重复上面的数）&quot;">​</a></h2><ul><li><strong>Link 在场景 ROM 里本来就没有纹理</strong>（2026-10-06 发现并修）：<code>src_scene/link_rigid.c</code> 整条路只绑 白纹理单位元 + 逐部位纯色，一次 <code>glTexCoord2f</code> 都没发 —— 而 <code>include/link_tex_groups.h</code> 里每组的 <code>tex_id</code> 与每顶点的 UV 一直都有，只是没人用（独立 ROM <code>src/link_full_render.c</code> 用的是完整那条链， 所以&quot;林克有纹理&quot;在旧交付里成立、在场景 ROM 里不成立）。新旋钮 <code>LINKTEX=1</code> 接上：上传 17 张 RGBA （与 <code>texInfos[]</code> <strong>同序</strong>，那是 <code>tex_id</code> 的编号契约）、<strong>逐组</strong>绑定（房间那条路的教训是整条 DL 只绑 一次会让后半段拿前半段的纹理）、纯色组继续走白纹理、逐顶点发 UV、<code>glPolyFmt</code> 加 <code>POLY_MODULATION</code>。 实测 <code>lkSceneTex.nds</code> = <code>83bd4dfa</code>：同机位与锚点逐像素比<strong>差 530 px，差异 bbox x112–149 / y149–191</strong> —— 正好是 Link 的剪影，房间与本体一个像素没动；<code>LINKTEX</code> 不传时锚点重编仍是 <code>dd9bfa50</code>。 交付 ROM 默认<strong>没开</strong>它（开了就是换验收实物），要不要转正等你决定。</li><li><strong>眼包素材的一处缺陷</strong>：偏差清单以前只记了「本体无纹理是范围决定」，<strong>没记「场景里的 Link 无纹理」</strong>， 画廊的&quot;不算缺陷&quot;列表里也没有 —— 于是看图的人只能得出&quot;该有纹理的地方是糊的&quot;。这条已经落到唯一上游： <code>docs/scene-port.md</code> §5 偏差 2 现在同时写明两处角色纹理的状态，<a href="/nds-site/caveats.html">已知偏差</a> 那页由它再生。</li><li><strong>眼包自己的血统规矩补齐</strong>：<code>_persp</code> 前三格背后的三台变体 ROM（<code>lkTexW b68af78a</code> / <code>lkTexFar 7f6c5831</code> / <code>lkBxFar d8e6f4d3</code>）此前从没按现源码逐位复现过 —— 按&quot;每张图的前缀必须能用当前源码逐位复现&quot;这条规矩， 那三格当时不算验收 ROM 的证据。今天整套照抄旋钮、逐台 <code>rm -rf build/&lt;NAME&gt;</code> 重编，三台<strong>全部逐位相同</strong>； <code>lkBxFar</code> 另做了 <code>LINKDRAW=0/1</code> 双产物交叉验证（第二次正好命中在册预测的 <code>bde1a5a1</code>），说明重建出的旋钮 集合唯一，不是碰巧对上。命令与结果逐字记在 <code>evidence/eye/manifest.txt</code>。这三台<strong>不在</strong>逐位复现名单里， 把它们加进去属于扩门，留给用户点头。</li><li><strong>发布面 == 在册实物</strong>：线上 8 张拼图逐张与 <code>evidence/eye/</code> 里的同名文件比字节，<strong>8/8 相同</strong>。这是&quot;你可以 直接在页面上投票&quot;的前提 —— 你看到的画面就是被复现过的那份 ROM 画出来的。第一遍有一张取回 0 字节（网络侧 偶发，重取即 200 且 md5 一致），别读成&quot;线上缺图&quot;。</li><li><strong>判读口径改了两处，都是&quot;别让评审人投出假 FAIL&quot;</strong>：<code>_persp</code>/终检里&quot;本体没有纹理&quot;是本轮的范围决定而不是缺陷 （<code>src_scene/boss</code> 那条链路只走顶点色）；终检第 1 格原写&quot;整场景对不对&quot;，但实测那个机位下入口房<strong>在相机背后</strong> （离线量具印它 0 px，而竞技场那间 49143 px），副屏那栏 <code>GPU 1018/1018</code> 是&quot;两间全量提交、未剔除&quot;，不等于 &quot;两间都看得见&quot;。</li><li><strong>仍然没闭合的只有一件事</strong>：协议 3 的人眼判决。机器侧四条协议都有当轮实测，但&quot;这就是森林 boss 房&quot;这句话 不能由量具自己说。另有两项等你决定：<code>tools/measure_walk.sh</code>/<code>measure_fps.sh</code> 是删掉还是给 ROM 加一条机器 可读输出通道（现 emulator 不转发宿主 printf），以及上面那句扩门。</li></ul>',3)])])}const h=d(n,[["render",a]]);export{p as __pageData,h as default};
